package com.bookflow.publiccatalog.application;
import com.bookflow.publiccatalog.api.PublicCatalogController.*; import com.bookflow.shared.error.ResourceNotFoundException; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Service; import java.util.*;
@Service @Profile("!test") public class PublicCatalogService {private final PublicCatalogRepository r;public PublicCatalogService(PublicCatalogRepository r){this.r=r;}private UUID t(String slug){return r.tenant(slug.strip().toLowerCase(Locale.ROOT)).orElseThrow(ResourceNotFoundException::new);}public PublicBusiness business(String s){return r.business(t(s));}public List<PublicBranch> branches(String s){return r.branches(t(s));}public List<PublicService> services(String s,UUID b){UUID t=t(s);if(b!=null&&!r.active(t,b,"branches"))throw new ResourceNotFoundException();return r.services(t,b);}public List<PublicEmployee> employees(String s,UUID b,UUID service){UUID t=t(s);if(!r.active(t,b,"branches")||(service!=null&&(!r.active(t,service,"services")||!r.serviceInBranch(t,service,b))))throw new ResourceNotFoundException();return r.employees(t,b,service);}}
